/// Whether a literal value is known to be a non-NaN value.
///
/// Returns `false` when the value is unknown (`None`) or cannot be determined, so that callers
/// treat those cases conservatively.
fn lv_is_definitely_not_nan(lv: Option<&LiteralValue>) -> bool {
    match lv {
        Some(lv) => match lv.to_any_value() {
            Some(AnyValue::Float32(f)) => !f.is_nan(),
            Some(AnyValue::Float64(f)) => !f.is_nan(),
            // A concrete non-float value is never NaN.
            Some(_) => true,
            None => false,
        },
        None => false,
    }
}

/// Whether a literal value is known to be NaN.
///
/// Returns `false` when the value is unknown (`None`) or cannot be determined.
fn lv_is_definitely_nan(lv: Option<&LiteralValue>) -> bool {
    match lv {
        Some(lv) => match lv.to_any_value() {
            Some(AnyValue::Float32(f)) => f.is_nan(),
            Some(AnyValue::Float64(f)) => f.is_nan(),
            _ => false,
        },
        None => false,
    }
}

/// Whether a `<`, `>`, `<=` or `>=` comparison on a float column can produce a skip-batch
/// predicate without violating NaN semantics.
///
/// Parquet statistics exclude NaN values, and Polars orders NaN as the largest float. As a result:
/// - `col < lit` / `col <= lit` are always safe: NaN never satisfies them, so a hidden NaN can
///   never be wrongly skipped.
/// - `col > lit` / `col >= lit` are only safe when `lit` is NaN, since nothing is greater (or
///   greater-or-equal) than NaN. For a non-NaN `lit` a hidden NaN would satisfy the comparison but
///   is invisible to the statistics.
///
/// `col_is_left` indicates whether the column is the left-hand operand; when it is not, the
/// operator direction is swapped before deciding (e.g. `lit > col` is equivalent to `col < lit`).
fn float_inequality_is_skippable(
    op: Operator,
    col_is_left: bool,
    lv: Option<&LiteralValue>,
) -> bool {
    use Operator as O;

    // Normalize so that the column is on the left-hand side.
    let effective = if col_is_left {
        op
    } else {
        match op {
            O::Lt => O::Gt,
            O::Gt => O::Lt,
            O::LtEq => O::GtEq,
            O::GtEq => O::LtEq,
            other => other,
        }
    };

    match effective {
        O::Lt | O::LtEq => true,
        O::Gt | O::GtEq => lv_is_definitely_nan(lv),
        _ => false,
    }
